window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-35201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστεκταίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4883 na letra π · nº geral 35201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fabricar ou maquinar além de. 〈πρός, τεκταίνω〉</p></section></article>\n<article id=\"entry-dgp-35202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστελέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4884 na letra π · nº geral 35202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pagar além de 2 pagar antecipadamente.</p></section></article>\n<article id=\"entry-dgp-35203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστέλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 4885 na letra π · nº geral 35203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enviar à frente 2 cobrir; proteger ♦ méd. 3 enviar à frente; impelir ♦ pas. 4 avançar; adiantar-se.</p></section></article>\n<article id=\"entry-dgp-35204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστενάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 4886 na letra π · nº geral 35204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gemer de antemão.</p></section></article>\n<article id=\"entry-dgp-35205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστένω</h1><div class=\"entry-meta\"><span>DGP · ordem 4887 na letra π · nº geral 35205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">προστενάζω.</p></section></article>\n<article id=\"entry-dgp-35206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστερνίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4888 na letra π · nº geral 35206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arreio para o peitoral dos cavalos 2 colarinho postiço (para atores). 〈πρός, στέρνον〉</p></section></article>\n<article id=\"entry-dgp-35207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόστερνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4889 na letra π · nº geral 35207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colocado sobre o peito (véu). 〈πρός, στέρνον〉</p></section></article>\n<article id=\"entry-dgp-35208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστεχνάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4890 na letra π · nº geral 35208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imaginar além.</p></section></article>\n<article id=\"entry-dgp-35209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστήκω</h1><div class=\"entry-meta\"><span>DGP · ordem 4891 na letra π · nº geral 35209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. intr. προστέτηκα, part. perf. dór. προσ­τετακώς) 1 fundir-se; consumir-se: δεινοτάτῳ μὲν ὕδρας προστετακώς sóf. consumido pela teia horrífica da Hidra ♦ pas. (aor.2 προσετάκην) 2 derreter-se sobre; consumir-se sobre; ser absorvido.</p></section></article>\n<article id=\"entry-dgp-35210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόστηξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4892 na letra π · nº geral 35210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o derreter-se sobre, o apegar-se a; aderência a. 〈προστήκω〉</p></section></article>\n<article id=\"entry-dgp-35211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστίθημι</h1><div class=\"entry-meta\"><span>DGP · ordem 4893 na letra π · nº geral 35211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. προσθήσω, aor. προσέθηκα, aor.2 προ­σέθην; méd. fut. προσθήσομαι, aor. προσεθηκάμην etc.; pas. aor.1 προσετέθην etc.) ativa 1 colocar perto ou contra; apor; aplicar algo, gen., sobre, dat. ou πρός, εἰς e ac. 2 atribuir; destinar; impor algo 3 imputar algo, ac., a alguém, dat. 4 atribuir; conceder; dar algo, ac., a alguém, dat. 5 impor; infligir algo, ac., a alguém, dat. 6 entregar; abandonar algo, ac., a alguém, dat. 7 causar; provocar, ac. 8 colocar algo, ac., em acréscimo a, dat.; acrescentar média 9 colocar algo, ac., na direção de alguém, dat. 10 aproximar de si; atrair para si ou sobre si, ac. 11 acrescentar algo, ac., a, dat. ou ἐπί, πρός e dat. 12 dispor de; ter a seu favor, dat. 13 tomar partido de; colocar-se a favor de alguém, dat.; aderir a; aprovar algo, dat. 1 σοῖς προστίθημι γόνασιν ὠλένας ἐμᾶς eur. apóio meus braços sobre teus joelhos, πρ. κλίμακας πύργοις tuc. apoiar escadas contra as torres, πρ. τὸ στόμα πρὸς τὸ στόμα xen. aplicar a boca sobre a de outro, πρ. τὴν φιλανθρωπίαν εἰς τὰ τῆς πόλεως πράγματα dem. aplicar o espírito humanitário aos negócios públicos, πρ. λίθον hom. fixar uma pedra diante (da entrada), πρ. τὰς πύλας tuc. fechar as portas 2 ἐν δρόμῳ πρ. μέτρον ésql. impor a medida na corrida 3 τῷ θεῷ προστίθης τὴν αἰτίαν eur. ao deus imputas a responsabilidade, μὴ τοῖς ὀλίγοις ἡ αἰτία προστεθῇ tuc. que a responsabilidade não seja imputada aos oligarcas 4 ταύτην ἠθέλησε τούτῳ γυναῖκα προσθεῖναι her. quis dá-la como como esposa a esse [heleno excelente], τέλεον δὲ γέρας προσέθηκεν ἑκάστῃ hin. a cada uma [das partes] conferiu honraria perfeita 5 καί τοι ταύτην τὴν ἀτιμίην προστίθημι her. e a ti inflijo esta desonra, ἐὰν δὲ προστιθῇ τὸ καρτερόν ésql. se ele impuser a violência 6 δεδιὼς μὴ ἐγώ τισι προσθῶ τὴν πόλιν tuc. temeroso de que eu entregue a cidade a alguns, Ἅιδῃ προστιθεῖσ’ ἐμὸν δέμας eur. tendo entregado meu corpo a Hades 7 πρ. ὄκνον πολύν sóf. provocar uma grande hesitação 8 χάριτι προσθεῖναι χάριν eur. acrescentar um favor a outro favor, προσθεὶς ὁ πατὴρ φερνὰς ἀπῴκισε eur. o pai, após acrescentar um dote, despacha-a [a mulher] de casa, μὴ νοσοῦντί μοι νόσον προσθῇς eur. não acrescentes uma doença a mim, que estou doente 9 πρ. ψῆφόν τινι ésql. dar seu voto a alguém, votar em favor de alguém, ψῆφον προσεθέμεθα ἐναντίαν ὑμῖν tuc. não depositamos voto contrário a vós, οἱ πόλεμον προσετέκαντο her. fizeram guerra contra eles, οὐκ ἄν σφι Σπαρτιήτας μῆνιν οὐδεμίαν προσθέσθαι her. [parece-me] que os espartanos não descarregariam sua cólera contra eles 10 πατρός γὲ προσθέσθαι στέρνα θέλω eur. quero aproximar de mim o peito de meu pai, i.e., quero abraçar meu pai, πρ. δάμαρτα sóf. tomar uma esposa, τὸν Ἀθηναίων δῆμον προσεθέκατο her. atraiu para si o povo ateniense 11 πρ. πρὸς κακοῖσι κακόν ésql. acrescentar um novo mal a outros males, ἄχθος τ’ ἐπ’ ἄχθει τῷδε προσθέσθαι διπλοῦν eur. acrescentar um duplo pesar a este pesar, πρ. τινὰ πολέμιον πρὸς τοῖς ἄλλοις xen. tornar alguém um inimigo acrescentado a outros, ἀπεκείραντο τὰς κεφαλὰς καὶ πένθος μέγα προσεθήκαντο her. [os milésios] raparam a cabeça e acrescentaram luto rigoroso 12 τούς τε Λακεδαιμονίων βασιλέας μὴ μιᾷ ψήφῳ προστίθεσθαι ἑκάτερον tuc. [presumem] que cada um dos reis dos lacedemônios dispõe não de um voto, mas de dois 13 οὔ οἱ ἔγωγε προσθήσομαι τῇ γνώμῃ her. eu não aderirei à opinião dele.</p></section></article>\n<article id=\"entry-dgp-35212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστιμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4894 na letra π · nº geral 35212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Jur. infligir a mais (uma pena), ac., a alguém, dat., em acréscimo a, πρός e dat.: πρ. πρὸς τῷ ἀργυρίῳ δεσμόν τινι dem. infligir a prisão a alguém, em acréscimo à multa ♦ méd. 2 Jur. (demandante) exigir uma pena suplementar contra o acusado ♦ pas. 3 impes. ser infligido como pena suplementar.</p></section></article>\n<article id=\"entry-dgp-35213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστίμησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4895 na letra π · nº geral 35213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">acréscimo de pena suplementar a uma pena legal. 〈πρός, τιμάω〉</p></section></article>\n<article id=\"entry-dgp-35214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστραχηλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 4896 na letra π · nº geral 35214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">agarrar pelo pescoço.</p></section></article>\n<article id=\"entry-dgp-35215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστρέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 4897 na letra π · nº geral 35215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 suplicar algo, ac., a alguém, ac. 2 suplicar; pedir com orações a alguém, ac., que, inf. 3 precipitar-se sobre; atacar, ac. ♦ méd. 4 virar-se para; dirigir-se para, ac. 5 dirigir-se, em súplica, a, ac.: προστραπέσθαι τούσδε δόμους ésql. dirigir-se como suplicante a este palácio 6 suplicar algo, ac. 7 voltar-se a alguém, ac., com veneração; venerar ♦ pas. 8 tornar-se objeto de súplica.</p></section></article>\n<article id=\"entry-dgp-35216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 4898 na letra π · nº geral 35216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">criar ou alimentar em acréscimo a, dat.</p></section></article>\n<article id=\"entry-dgp-35217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστρέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 4899 na letra π · nº geral 35217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. προσδραμοῦμαι, aor.2 προσέδραμον etc.) 1 correr em direção a alguém, dat. ou πρός e ac. 2 atirar-se contra, πρός e ac. 3 pôr-se do lado de, dat. ou πρός e ac.: πρ. πρὸς τὴν ἀλήθειαν pol. aproximar-se da verdade.</p></section></article>\n<article id=\"entry-dgp-35218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστρίβω</h1><div class=\"entry-meta\"><span>DGP · ordem 4900 na letra π · nº geral 35218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esfregar; friccionar contra; gastar 2 fazer participar de; comunicar; atribuir algo, ac., a alguém, dat. ♦ méd. 3 esfregar algo, ac., contra, dat.: πληγὰς ἀεὶ προστρίβεται τοῖς οἰκέταις ar. sempre assenta pancadas nos servos, πρ. τινὶ ὑποψίαν προδοσίας plut. infligir a alguém a suspeita de traição 4 atribuir; imputar algo, ac., a alguém, dat.: πρ. τινὶ πλούτου δόξαν dem. imputar a alguém a fama de rico.</p></section></article>\n<article id=\"entry-dgp-35219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόστριμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4901 na letra π · nº geral 35219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desgraça; infortúnio que cai sobre alguém 2 destroço; resto; fragmento. 〈προστρίβω〉</p></section></article>\n<article id=\"entry-dgp-35220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστρόπαιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4902 na letra π · nº geral 35220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 suplicante: λιταὶ προστρόπαιοι sóf. súplicas 2 que exige vingança; vingador 3 culpado de crime que exige expiação 4 impuro; criminoso 5 vingador do crime ou protetor dos suplicantes (deus) ♦ τὸ προστρόπαιον 6 atentado; crime. 〈προστροπή〉</p></section></article>\n<article id=\"entry-dgp-35221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστροπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4903 na letra π · nº geral 35221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 oração; súplica a alguém, gen.; θεᾶς ἔχειν προστροπήν eur. ter a função de aplacar a deusa, i.e., ser sacerdote ou sacerdotisa 2 maldição; imprecação. 〈προστρέπω〉</p></section></article>\n<article id=\"entry-dgp-35222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόστροπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4904 na letra π · nº geral 35222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que dirige súplicas a alguém, gen. 〈προστρέπω〉</p></section></article>\n<article id=\"entry-dgp-35223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστυγχάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 4905 na letra π · nº geral 35223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. προστεύξομαι, aor.2 προσέτυχον) 1 expor-se aos olhares; encontrar-se por acaso: ὁ προσ­τυχών tuc. o primeiro que aparece, i.e., qualquer um, τὸ προσ­τυχόν plat. a primeira coisa que aparece, i.e., qualquer coisa, κατὰ τὸ προστυχόν ou ἐκ τοῦ προστυχόντος plut. segundo a ocorrência, de improviso 2 encontrar, dat. 3 obter, gen.</p></section></article>\n<article id=\"entry-dgp-35224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστῷον</h1><div class=\"entry-meta\"><span>DGP · ordem 4906 na letra π · nº geral 35224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e πρόστῳον, ου (τό) pórtico colocado em frente de um edifício; vestíbulo.</p></section></article>\n<article id=\"entry-dgp-35225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυγγίγνομαι,</h1><div class=\"entry-meta\"><span>DGP · ordem 4907 na letra π · nº geral 35225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. προξυγγίγνομαι 1 conferenciar previamente com, dat. 2 pôr-se previamente de acordo com, dat.</p></section></article>\n<article id=\"entry-dgp-35226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυμμίσγω</h1><div class=\"entry-meta\"><span>DGP · ordem 4908 na letra π · nº geral 35226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">misturar antes.</p></section></article>\n<article id=\"entry-dgp-35227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυνίστημι</h1><div class=\"entry-meta\"><span>DGP · ordem 4909 na letra π · nº geral 35227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. προσυστήσω, aor. συνέστησα etc.) recomendar antecipadamente.</p></section></article>\n<article id=\"entry-dgp-35228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυνοικέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4910 na letra π · nº geral 35228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 habitar anteriormente com, dat. 2 habitar também com, dat.</p></section></article>\n<article id=\"entry-dgp-35229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυπερβάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 4911 na letra π · nº geral 35229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ultrapassar além de ou ainda.</p></section></article>\n<article id=\"entry-dgp-35230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυπεργάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4912 na letra π · nº geral 35230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">preparar para; facilitar a, dat.</p></section></article>\n<article id=\"entry-dgp-35231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυπισχνέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4913 na letra π · nº geral 35231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prometer em acréscimo, inf.</p></section></article>\n<article id=\"entry-dgp-35232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυποβάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 4914 na letra π · nº geral 35232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colocar também debaixo.</p></section></article>\n<article id=\"entry-dgp-35233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσυποθήγω</h1><div class=\"entry-meta\"><span>DGP · ordem 4915 na letra π · nº geral 35233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aguçar contra, dat.</p></section></article>\n<article id=\"entry-dgp-35234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφαγεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 4916 na letra π · nº geral 35234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 (imper. πρόσφαγε) comer além.</p></section></article>\n<article id=\"entry-dgp-35235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφάγημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4917 na letra π · nº geral 35235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o que se come além do pão; ração suplementar. 〈προσφαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-35236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφάγιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4918 na letra π · nº geral 35236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">peixe.</p></section></article>\n<article id=\"entry-dgp-35237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφαγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4919 na letra π · nº geral 35237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sing. ou pl. vítima oferecida em sacrifício 2 sacrifício. 〈πρός, σφάζω〉</p></section></article>\n<article id=\"entry-dgp-35238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφαίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4920 na letra π · nº geral 35238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mostrar-se além de.</p></section></article>\n<article id=\"entry-dgp-35239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφάσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4921 na letra π · nº geral 35239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. πρόσφημι.</p></section></article>\n<article id=\"entry-dgp-35240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4922 na letra π · nº geral 35240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que acaba de ser morto; morto recentemente 2 fresco; recente; novo 3 jovem ♦ πρόσ­φατον adv. 4 recentemente.</p></section></article>\n<article id=\"entry-dgp-35241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφερής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 4923 na letra π · nº geral 35241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se relaciona com; que tem alguma relação com; semelhante a, dat. 2 útil; vantajoso para, dat. 〈προσφέρω〉</p></section></article>\n<article id=\"entry-dgp-35242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφέρτατος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4924 na letra π · nº geral 35242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito nobre.</p></section></article>\n<article id=\"entry-dgp-35243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 4925 na letra π · nº geral 35243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. προσοίσω, aor. προσήνεγκα etc.; méd. aor. προσηνεγκάμην; pas. aor. προσηνέχθην) ativa 1 trazer para perto; apoiar algo, ac., contra, dat. 2 levar algo, ac., na direção de ou para, dat. 3 dizer; proferir algo, ac., a alguém, dat.; λόγους πρ. fazer negociações com alguém, dat., a respeito de, περί e gen., ou para, inf. 4 trazer; apresentar; oferecer 5 apresentar; oferecer em acréscimo (ao tributo pago) 6 pagar contribuições (taxa, imposto); contribuir com o pagamento de, ac. 7 aplicar algo, ac., contra alguém, dat.; πρ. χεῖράς τινι levantar a mão para alguém, empregar a força 8 acrescentar uma coisa, ac., a outra, dat. ou πρός e ac. média 9 comportar-se 10 levar à boca algo, ac. 11 mostrar; testemunhar algo, ac., em relação a, dat. 12 empregar algo, ac., em, dat. passiva 13 dirigir-se para; aproximar-se de, dat. ou πρός e ac. 14 lançar-se sobre alguém ou algo, dat.; lançar-se contra alguém, πρός e ac. 15 (fato) apresentar-se; acontecer 16 comportar-se; conduzir-se em relação a alguém, dat., ou a algo, dat. ou πρός e ac. 17 usar de; manejar, ac. ou dat. 18 aproximar-se de; ter a ver com; ser análogo ou parecido com alguém, εἰς e ac. 1 προσφέρειν πύργοισι πηκτῶν κλιμάκων προσαμβά­σεις eur. apoiar nas torres escadas de firmes degraus 2 τῷ μὲν φάρμακα καὶ τροφὴν προσφέρων ὑγίειαν καὶ ῥώμην ἐμποιήσειν plat. levando para ele [o corpo] remédios e alimento para incutir saúde e força 3 ἡ Ἄτοσσα προσέφερε ἐν τῇ κοίτῃ Δαρείῳ λόγον τοιόνδε her. Atossa proferiu, no leito, tais palavras a Dario, λόγους προσφέρουσι περὶ ξυμβάσεως τοῖς στρατηγοῖς tuc. fazem negociações com os generais a respeito do tratado, προσέφερε δὲ λόγους καὶ τοῖς ἐπὶ Θρᾴκης Χαλκιδεῦσι καὶ Βοττιαίοις ξυναποστῆναι tuc. fazia ainda negociações com os calcídios da Trácia e com os botieus para que juntos entrassem em sedição 4 τῷ δὲ Κύρῳ καὶ τοῖς ἀμφ’ αὐτὸν προσήνεγκαν οἱ θεράποντες ἐμφαγεῖν καὶ πιεῖν xen. e para Ciro e o seu séquito os servos trouxeram de comer e de beber, τὰ προσφερόμενα hipócr. o que se toma (refeição; alimento; remédio) 5 δῶρα χρυσοῦ τε καὶ ἀργύρου προσεφέρετο tuc. em acréscimo [ao tributo pago] eram oferecidos presentes de ouro e de prata 6 πρ. μετοίκιον xen. pagar a taxa dos metecos, προσέφερε πεντήκοντα τάλαντα τοῦ ἐνιαυτοῦ tuc. [a Magnésia] contribuía com o pagamento de cinquenta talentos por ano 7 οὐκ ἔστιν ἐν τῇ ἐμῇ ἐπιστήμῃ τὸ τὰς χεῖρας προσ­φέροντα ποιεῖν ὑπομένειν τοὺς καλούς xen. não é do meu perfil levantar a mão, i.e., empregar a força para fazer os bons submeterem-se, Καμβύσης γὰρ βίην οὐκ ἐδικαίου προσφέρειν Φοίνιξι her. Cambises não achou oportuno valer-se de força contra os fenícios, σοὶ δὲ δὴ μέλλει τίς ὦ βασιλεῦ ἀντιώσεσθαι πόλεμον προφέρων; her. mas a ti, rei, quem irá se opor, fazendo guerra? 8 μηδὲ προσφέρειν μέθυ sóf. não acrescentar vinho (à água e ao mel), κακὸν πρ. νέον παλαιῷ eur. acrescentar um novo mal a um antigo, ὁ δὲ Ἀλκμέων πρὸς τὴν δωρεὴν ἐοῦσαν τοιαύτην τοιάδε ἐπιτηδεύσας προσέφερε her. Alcméon, perante uma oferta de tal natureza, acrescentou tal expediente 9 τὴν μὲν τῶν Ἀθηναίων φρουρὰν ἐξήγαγεν ἐκ τῆς πόλεως καὶ φιλανθρώπως αὐτῇ προσενεγκάμενος ἐξαπέστειλεν εἰς τὰς Ἀθήνας d.s. [Filipe] retirou da cidade a guarnição ateniense e, tratando-a com humanidade, despachou-a de volta a Atenas 10 νῦν μοι δοκεῖ τοιοῦτον σῖτον ἡμᾶς προσφέρεσθαι δεῖν καὶ τοιοῦτον πότον xen. agora parece-me que devemos levar à boca esse tipo de comida e esse tipo de bebida 11 πρ. πᾶσαν ὑμῖν φιλοτιμίαν dem. dar mostras de todo o interesse por vós 12 πρ. πᾶσαν σπουδὴν καὶ μηχανήν τινι pol. empregar em algo toda espécie de cuidados e de recursos 13 προσφέρεσθαι τοῖσι Κορινθίοισι her. ir aos coríntios, ὥσπερ εἰς λιμένα ἐκ χειμῶνος προσφέρεσθαι αὐτούς xen. como se eles se aproximassem de um porto fugindo de uma borrasca, ἑτέροισι ὑπηρέτησι πρ. καὶ πρὸς ἵππον her. encaminhar-se para os outros criados e para o cavalo 14 αἵρεσιν ὑμῖν δίδομεν ἡμεῖς οἱ Κύπριοι ὁκοτέροισι βούλεσθε προσφέρεσθαι, ἢ Πέρσῃσι ἢ Φοίνιξι her. nós os cíprios vos concedemos o direito de escolher contra qual dos dois desejais lançar-vos, contra os persas ou contra os fenícios 15 τὰ προσφερόμενα πρήγματα her. os acontecimentos 16 σαφὲς ἂν καταστήσαιτε αὐτοῖς ἀπὸ τοῦ ἴσου ὑμῖν μᾶλλον προσφέρεσθαί tuc. estabeleceríeis de modo claro que eles devem tratar-vos de igual para igual, ὡς φίλοι προσεφέροντο ἡμῖν xen. comportavam-se conosco como amigos, πρ. πρός τινα μετὰ πρᾳότητος isócr. portar-se com alguém com gentileza, πρ. ταῖς ξυμφοραῖς tuc., πρ. πρὸς τὰ πράγματα tuc. comportar-se (de tal ou de tal maneira) com relação aos acontecimentos, aos negócios, πρ. ῥᾳθύμως καὶ ἀνάνδρως τοῖς πολεμικοῖς herod. comportar-se na guerra com moleza e sem energia 17 ὀρθότατα ἵπποις προσφέρεσθαι xen. controlar muito bem os cavalos 18 καί οἱ ὅ τε χαρακτὴρ τοῦ προσώπου προσφέρεσθαι ἐδόκεε ἐς ἑωυτόν her. e lhe [a Astíages] parecia que os traços fisionômicos dele [Ciro] eram semelhantes aos seus.</p></section></article>\n<article id=\"entry-dgp-35244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφερῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 4926 na letra π · nº geral 35244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com semelhança; semelhantemente. 〈προσφέρω〉</p></section></article>\n<article id=\"entry-dgp-35245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφεύγω</h1><div class=\"entry-meta\"><span>DGP · ordem 4927 na letra π · nº geral 35245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 refugiar-se junto a, dat. 2 ser acusado além.</p></section></article>\n<article id=\"entry-dgp-35246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφημι</h1><div class=\"entry-meta\"><span>DGP · ordem 4928 na letra π · nº geral 35246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ou aor.2 προσέφην, fut. προσφήσω; inf. aor.2 méd.προσφάσθαι) at. e méd. dirigir a palavra a, ac. 〈πρός, φημί〉</p></section></article>\n<article id=\"entry-dgp-35247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφθέγγομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4929 na letra π · nº geral 35247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dirigir a palavra a; saudar, ac. 2 designar por um nome; nomear.</p></section></article>\n<article id=\"entry-dgp-35248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφθεγκτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 4930 na letra π · nº geral 35248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 a quem a palavra é dirigida: πρ. φωνῆς τινος sóf. saudado ou interpelado pela voz de alguém 2 que dirige a palavra; que saúda. 〈προσφθέγγομαι〉</p></section></article>\n<article id=\"entry-dgp-35249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφθεγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4931 na letra π · nº geral 35249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 palavra dirigida a alguém 2 apelo; chamamento. 〈προσφθέγγομαι〉</p></section></article>\n<article id=\"entry-dgp-35250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφθείρομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4932 na letra π · nº geral 35250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ligar-se ou estar ligado a má companhia; perder-se com a companhia de, dat.</p></section></article>\n<article id=\"entry-dgp-35251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφθογγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4933 na letra π · nº geral 35251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que serve para dirigir a palavra ou para saudar. 〈προσφθέγγομαι〉</p></section></article>\n<article id=\"entry-dgp-35252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφθονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4934 na letra π · nº geral 35252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser além do mais invejoso; querer mais.</p></section></article>\n<article id=\"entry-dgp-35253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφίλεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4935 na letra π · nº geral 35253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">benevolência; boa vontade; cordialidade. 〈προσφιλής〉</p></section></article>\n<article id=\"entry-dgp-35254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφιλής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 4936 na letra π · nº geral 35254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de amizade ou de benevolência por, dat. 2 amado; querido; agradável a, dat. ou gen. 〈πρός, φιλέω〉</p></section></article>\n<article id=\"entry-dgp-35255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφιλοσοφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4937 na letra π · nº geral 35255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 especular ainda sobre, dat.; τῷ λόγῳ πρ. plat. continuar a pesquisa filosófica 2 filosofar em companhia de, dat.</p></section></article>\n<article id=\"entry-dgp-35256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφιλοσοφητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 4938 na letra π · nº geral 35256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de προσφιλοσοφέω.</p></section></article>\n<article id=\"entry-dgp-35257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφιλοτιμέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4939 na letra π · nº geral 35257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aplicar-se com amor-próprio ou emulação a, dat.</p></section></article>\n<article id=\"entry-dgp-35258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφιλῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 4940 na letra π · nº geral 35258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com disposições amigáveis ou benevolentes.</p></section></article>\n<article id=\"entry-dgp-35259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφοιτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4941 na letra π · nº geral 35259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ir frequentemente a casa de, dat. ou πρός e ac.; frequentar.</p></section></article>\n<article id=\"entry-dgp-35260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφορά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4942 na letra π · nº geral 35260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de levar para ou para junto de 2 ação de colocar ao alcance; oferecimento 3 ação de levar a mais, de acrescentar; acréscimo 4 benfeitoria; ganho; proveito 5 presente 6 bíbl. oferenda 7 crist. oferenda ou celebração eucarística 8 que se leva (à boca); alimento 9 odor 10 salário; remuneração. 〈προσφέρω〉</p></section></article>\n<article id=\"entry-dgp-35261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4943 na letra π · nº geral 35261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">trazer; levar.</p></section></article>\n<article id=\"entry-dgp-35262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4944 na letra π · nº geral 35262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que responde a; adaptado a; proporcional a, dat.; πρόσφορόν ἐστι com inf. convém, é adequado 2 conveniente 3 que se assemelha a; análogo a, dat. 4 útil a; vantajoso a, dat. 5 que se acrescenta ou que se pode acrescentar ♦ τὸ πρόσφορον 6 alimento 7 pl. as coisas necessárias. 〈προσφέρω〉</p></section></article>\n<article id=\"entry-dgp-35263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφυγος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 4945 na letra π · nº geral 35263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) = πρόσφυξ.</p></section></article>\n<article id=\"entry-dgp-35264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφυέως</h1><div class=\"entry-meta\"><span>DGP · ordem 4946 na letra π · nº geral 35264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = προσφυῶς.</p></section></article>\n<article id=\"entry-dgp-35265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφυής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 4947 na letra π · nº geral 35265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que cresce sobre 2 fixado a; preso a; apegado a, ἐκ e gen. 3 ligado a; dado a, dedicado a, dat. 4 que se liga naturalmente a; naturalmente adequado a; nascido para, dat. 〈προσφύω〉</p></section></article>\n<article id=\"entry-dgp-35266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφυξ, υγος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4948 na letra π · nº geral 35266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que se refugia junto a, que se põe sob a proteção de alguém, gen. 2 adepto (de uma causa ou partido).</p></section></article>\n<article id=\"entry-dgp-35267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφύω</h1><div class=\"entry-meta\"><span>DGP · ordem 4949 na letra π · nº geral 35267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. προσφύσω, aor. προσέφυσα) 1 fazer nascer ou crescer sobre 2 fazer aderir 3 estabelecer fortemente; confirmar ♦ at. (aor.2 προσέφυν, part. προσ­φύς, προσφῦσα, perf. προσπέφυκα) e méd. pas. προσφύομαι (fut. προσφύσομαι) 4 nascer ou crescer sobre, dat. 5 ser ligado ou ligar-se a; apegar-se fortemente a, dat. 6 ligar-se a; aplicar-se a; associar-se a, dat.</p></section></article>\n<article id=\"entry-dgp-35268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφυῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 4950 na letra π · nº geral 35268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 intimamente; de perto 2 de modo apropriado; convenientemente 3 oportunamente.</p></section></article>\n<article id=\"entry-dgp-35269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφωνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4951 na letra π · nº geral 35269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dirigir a palavra a alguém, ac. ou dat. 2 proferir; pronunciar algo, ac.; dizer algo, ac., a alguém, dat. 3 chamar alguém, ac., por um nome ou por um título, ac.: πρ. τινὰ βασιλέα pol. proclamar alguém rei 4 dedicar algo, ac., a alguém, dat.</p></section></article>\n<article id=\"entry-dgp-35270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφώνημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4952 na letra π · nº geral 35270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 palavra; discurso 2 carta endereçada a alguém 3 aquele a quem a palavra é dirigida. 〈προσφωνέω〉</p></section></article>\n<article id=\"entry-dgp-35271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφώνησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4953 na letra π · nº geral 35271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 palavras ou discursos dirigidos a alguém 2 carta 3 dedicatória. 〈προσφωνέω〉</p></section></article>\n<article id=\"entry-dgp-35272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 4954 na letra π · nº geral 35272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. προσχανοῦμαι, perf. com sent. de pres. προσκέχηνα) 1 abrir bem com a boca (para gritar): μηδὲ χαμαιπετὲς βόαμα προσχάνῃς ἐμοί ésql. nem me aclames prostrada aos gritos 2 olhar de boca aberta; ficar perplexo diante de, dat. 3 dedicar-se totalmente a, dat.</p></section></article>\n<article id=\"entry-dgp-35273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχαίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 4955 na letra π · nº geral 35273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alegrar-se com, dat.</p></section></article>\n<article id=\"entry-dgp-35274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχαρίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4956 na letra π · nº geral 35274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comprazer; agradar a, dat.</p></section></article>\n<article id=\"entry-dgp-35275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 4957 na letra π · nº geral 35275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de προέχω.</p></section></article>\n<article id=\"entry-dgp-35276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχέω</h1><div class=\"entry-meta\"><span>DGP · ordem 4958 na letra π · nº geral 35276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. προσέχεον, fut. προσχεῶ, aor. προσέχεα, aor. pas. προσεχύθην) 1 verter algo, ac., em ou sobre, dat. 2 derramar algo, ac., em acréscimo a algo, dat. ♦ méd. 3 verter água sobre si; banhar-se.</p></section></article>\n<article id=\"entry-dgp-35277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσχημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4959 na letra π · nº geral 35277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apresto; aparato; pompa; magnificência 2 ornamento: Ἑλλάδος πρόσχημ᾿ἀγῶνος sóf. adorno dos jogos públicos da Grécia 3 pretexto; razão enganosa; máscara: πρ. ποιεῖθαι ὡς com ind. her., ou ποιεῖσθαι com inf. tuc. tomar ou dar por pretexto que 4 começo; introdução 5 o que se mostra; aspecto; aparência ♦ πρόσχημα adv. 6 em aparência. 〈προέχω〉</p></section></article>\n<article id=\"entry-dgp-35278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4960 na letra π · nº geral 35278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">προσχώννυμι.</p></section></article>\n<article id=\"entry-dgp-35279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχράομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 4961 na letra π · nº geral 35279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">usar em acréscimo algo, dat., para algo, εἰς, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-35280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχρῄζω</h1><div class=\"entry-meta\"><span>DGP · ordem 4962 na letra π · nº geral 35280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ter necessidade ainda de, gen. 2 pedir ainda algo, gen.; pedir a alguém, ac. ou gen., que, inf.: πρ. τινὸς πείθεσθαί τινι her. pedir a alguém que obedeça a outrem ou ou que siga os conselhos de outrem.</p></section></article>\n<article id=\"entry-dgp-35281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχρηΐζω</h1><div class=\"entry-meta\"><span>DGP · ordem 4963 na letra π · nº geral 35281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = προσχρῄζω.</p></section></article>\n<article id=\"entry-dgp-35282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσχρησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4964 na letra π · nº geral 35282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">uso suplementar de algo. 〈προσχράομαι〉</p></section></article>\n<article id=\"entry-dgp-35283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσχυσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4965 na letra π · nº geral 35283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. aspersão. 〈προσχέω〉</p></section></article>\n<article id=\"entry-dgp-35284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσχω</h1><div class=\"entry-meta\"><span>DGP · ordem 4966 na letra π · nº geral 35284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 de προέχω ou προσέχω.</p></section></article>\n<article id=\"entry-dgp-35285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσχωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4967 na letra π · nº geral 35285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aterro; aluvião. 〈πρός, χώννυμι〉</p></section></article>\n<article id=\"entry-dgp-35286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχώννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 4968 na letra π · nº geral 35286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cobrir com um monte de terra; (água) formar aluviões 2 erguer um aterro junto a 3 intr. formar aterro ♦ pas. 4 ser ligado ao continente por terras de aluvião.</p></section></article>\n<article id=\"entry-dgp-35287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσχωρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4969 na letra π · nº geral 35287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encaminhar-se para; aproximar-se de, dat. 2 passar para o lado de; juntar-se a, dat. ou πρός e ac.: προσεχώρησαν δὲ καὶ Μεγαρῆς Ἀθηναίοις ἐς ξυμμαχίαν tuc. também os megarenses juntaram-se aos atenienses em aliança, τοῖς τοῦδε προσχωρεῖν λόγοις sóf. ceder às palavras deste [de Filoctetes], οὐκ ἐθέλει οὐδὲ ὁ θεὸς προσχωρέειν πρὸς τὰς ἀνθρωπηίας γνώμας her. nem o deus quer ceder à opinião humana 3 ger. no perf., aproximar-se, por semelhança, de; ter relação por semelhança com, dat. ou πρός e ac.: τὰ δὲ ἄλλα νόμαια Θρήιξι προσκεχωρήκασι her. quanto aos demais costumes, eles guardam semelhança com os trácios, προσκεχωρήκασι δὲ γλῶσσαν μὲν πρὸς τὸ Καρικὸν ἔθνος her. quanto à língua, [os cáunios] guardam semelhança com a raça cária 4 ter confiança em, dat.</p></section></article>\n<article id=\"entry-dgp-35288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσχωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4970 na letra π · nº geral 35288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 limítrofe; vizinho de, dat. ♦ ὁ πρόσχωρος 2 vizinho de, gen. ou dat. 〈πρός, χώρα〉</p></section></article>\n<article id=\"entry-dgp-35289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσχωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4971 na letra π · nº geral 35289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aterro 2 aluvião. 〈προσχώννυμι〉</p></section></article>\n<article id=\"entry-dgp-35290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσψαύω,</h1><div class=\"entry-meta\"><span>DGP · ordem 4972 na letra π · nº geral 35290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. e poét. ποτιψαύω tocar em alguém, gen.</p></section></article>\n<article id=\"entry-dgp-35291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 4973 na letra π · nº geral 35291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. πρόσσω, át. πόρρω adv. πρόσω ou τὸ πρόσω 1 (lugar) à frente; para frente: οὐδ’ ἔχει βῆναι πρόσω sóf. ele não consegue seguir em frente 2 (lugar) ao longe; longe 3 (tempo) para frente; no futuro: ὁρᾶν πρόσσω καὶ ὀπίσσω hom. ter olhos no futuro e no passado ♦ prep. 4 (lugar) avante em, gen.: προβήσομαι ἐς τὸ πρόσω τοῦ λόγου her. irei avante no relato, μὴ πρόσω δὲ τοῦ ποταμοῦ προβαίνειν xen. [ordena que eles] não avancem para o interior do rio, i.e., para a parte funda do rio, οὐκ οἴει ἄν, ἔφη, πρόσω πάνυ ἐλάσαι τῆς πρὸς τοὺς πολεμίους πλεονεξίας; xen. não achas, disse, que já estarias assaz adiantado na ambição sobre os inimigos? πόρρω φιλοσοφίας ἐλαύνειν plat. mergulhar na filosofia, ἐς τὸ πρόσω οὐδὲν προεκόπτετο τῶν πρηγμάτων her. nenhum avanço acontecia nos empreendimentos 5 longe de, gen. ou ἀπό e gen.: οὐ πρόσω τοῦ Ἑλλησπόντου her. não longe do Helesponto, πρόσω ἀπὸ τῆς πόλεως isócr. longe da cidade 6 (tempo) bem tarde; muito tarde, gen.: πρόσω ἦν τῆς νυκτός her. era bem tarde da noite 7 além de, gen.: οὐ πόρρω ἑπτὰ ἡμερέων her. não além de sete dias. 〈πρό〉</p></section></article>\n<article id=\"entry-dgp-35292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσῳδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4974 na letra π · nº geral 35292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 canto para acompanhamento de lira 2 modulação da voz 3 inflexão ou modulação ou alteração do som de uma vogal, indicada por acento, espírito ou quantidade. 〈προσῳδός〉</p></section></article>\n<article id=\"entry-dgp-35293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσῳδός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 4975 na letra π · nº geral 35293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se canta com acompanhamento de um instrumento 2 que se afina com, dat. 3 afinado; harmonioso 4 que convém a, dat. 〈πρός, ᾄδω〉</p></section></article>\n<article id=\"entry-dgp-35294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσωθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 4976 na letra π · nº geral 35294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 (lugar) de longe 2 (tempo) há muito tempo. 〈πρόσω, -θεν〉</p></section></article>\n<article id=\"entry-dgp-35295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσωνυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4977 na letra π · nº geral 35295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cognome; sobrenome. 〈πρός, ὄνομα〉</p></section></article>\n<article id=\"entry-dgp-35296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσώτατα, προσώπασι</h1><div class=\"entry-meta\"><span>DGP · ordem 4978 na letra π · nº geral 35296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">plur. ép. de πρόσωπον.</p></section></article>\n<article id=\"entry-dgp-35297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσωπεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4979 na letra π · nº geral 35297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 máscara de teatro; máscara 2 ator 3 personagem. 〈πρόσωπον〉</p></section></article>\n<article id=\"entry-dgp-35298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσωπολημπτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 4980 na letra π · nº geral 35298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. mostrar parcialidade; ser parcial. 〈πρόσωπον, λαμβάνω〉</p></section></article>\n<article id=\"entry-dgp-35299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσωπολήμπτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4981 na letra π · nº geral 35299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. pessoa que se mostra parcial.</p></section></article>\n<article id=\"entry-dgp-35300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσωπολημψία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 4982 na letra π · nº geral 35300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. parcialidade. 〈προσωπο­λήμπτης〉</p></section></article>\n";
